<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElAlert, ElButton, ElCard, ElCheckbox, ElDialog, ElForm, ElInput, ElInputNumber, ElMessage, ElMessageBox, ElPagination, ElProgress, ElTable, ElTableColumn, ElTag } from 'element-plus'
import { classification } from '../api/classification'
import ClassificationEditor from '../components/ClassificationEditor.vue'
import { dimensionNames, originNames, statusNames, type Dimension, type Item, type Preview, type SaveSettings, type Start, type Tag, type Task } from '../types'
function toggleList(list: Dimension[], dim: Dimension, checked: boolean) { const at = list.indexOf(dim); if (checked && at < 0) list.push(dim); else if (!checked && at >= 0) list.splice(at, 1) }

const route = useRoute(), router = useRouter()
const tab = ref('tasks'), error = ref(''), busy = ref(false), loading = ref(false), tags = ref<Tag[]>([])
const config = ref<SaveSettings>({ enabled: false, endpoint: '', model: '', apiKey: '', clearKey: false, timeoutSeconds: 60, intervalSeconds: 3 }), hasKey = ref(false), settingsOpen = ref(false), settingsLoaded = ref(false)
const configDirty = ref(false)
const tasks = ref<Task[]>([]), task = ref<Task | null>(null), taskPage = ref(0), page = ref(1), filter = ref(''), loadedAt = ref('')
const dimensions = ref<Dimension[]>(['LANGUAGE', 'DECADE', 'GENRE', 'MOOD', 'SCENE']), automatic = ref<Dimension[]>([]), auto = ref(false), all = ref(false)
const selectedIds = computed(() => typeof route.query.songIds === 'string' ? route.query.songIds.split(',').filter(Boolean) : [])
const aiDimensions = (Object.keys(dimensionNames) as Dimension[]).filter(d => d !== 'CUSTOM')
const pendingPreview = ref<Preview | null>(null), pendingStart = ref<Start | null>(null)
const editing = ref<string[]>([]), reviewing = ref<Item | null>(null), reviewDims = ref<Dimension[]>([])
const tagEdit = ref<{ id?: string; dimension: Dimension; name: string; aliases: string; active: boolean; revision: number } | null>(null), tagSearch = ref(''), tagDimension = ref('')
const visibleTags = computed(() => tags.value.filter(t => (!tagDimension.value || t.dimension === tagDimension.value) && (!tagSearch.value || [t.name, ...t.aliases].some(n => n.includes(tagSearch.value)))))
const progress = computed(() => task.value?.total ? Math.round(task.value.completed * 100 / task.value.total) : 0)
let active = true, timer: ReturnType<typeof setTimeout> | undefined, generation = 0
const requestIds = new Map<string, string>()
function requestId(key: string) { let value = requestIds.get(key); if (!value) { value = crypto.randomUUID(); requestIds.set(key, value) } return value }
function dimensionLabels(dims: Dimension[]) { return dims.map(d => dimensionNames[d]).join('、') }
async function testConnection() { await perform(async () => { const result = await classification.test(); ElMessage.success(result.message) }) }
function names(ids: string[] = []) { return ids.map(id => tags.value.find(t => t.id === id)?.name ?? id).join('、') || '未知 / 无建议' }
function notifyFailure(e: unknown) { error.value = e instanceof Error ? e.message : '请求失败' }
async function perform(action: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; try { await action() } catch (e) { notifyFailure(e) } finally { busy.value = false } }
async function readSettings() { const saved = await classification.settings(); hasKey.value = saved.hasKey; config.value = { ...saved, apiKey: '', clearKey: false }; settingsLoaded.value = true; configDirty.value = false; settingsOpen.value = !saved.enabled }
async function saveSettings() {
  if (task.value?.status === 'RUNNING') { try { await ElMessageBox.confirm('保存模型设置将暂停进行中的分类任务。已有任务继续使用创建时的模型和词表快照；关闭模型后不能继续任务。', '保存设置', { type: 'warning' }) } catch { return } }
  await perform(async () => { await classification.saveSettings(config.value); await readSettings(); await refresh(); ElMessage.success('设置已保存；进行中的分类任务已暂停') })
}
async function refresh() {
  const token = ++generation; loading.value = true
  try {
    const id = typeof route.query.task === 'string' ? route.query.task : ''
    const [list, current] = await Promise.all([classification.tasks(taskPage.value), id ? classification.task(id, page.value - 1, filter.value) : Promise.resolve(null)])
    if (!active || token !== generation) return
    tasks.value = list; task.value = current; loadedAt.value = new Date().toLocaleTimeString(); error.value = ''
  } catch (e) { if (active && token === generation) notifyFailure(e) } finally { if (active && token === generation) loading.value = false }
}
function poll() { timer = setTimeout(async () => { if (!active) return; if (task.value?.status === 'RUNNING' || task.value?.status === 'PAUSED' && task.value.counts.PROCESSING) await refresh(); poll() }, 4000) }
async function preview() {
  await perform(async () => { const input: Start = { all: all.value, songIds: selectedIds.value, dimensions: [...dimensions.value], autoDimensions: auto.value ? automatic.value.filter(d => dimensions.value.includes(d)) : [] }; pendingPreview.value = await classification.preview(input); pendingStart.value = input })
}
async function start() {
  if (!pendingStart.value) return
  await perform(async () => { const result = await classification.start(pendingStart.value!); pendingStart.value = null; pendingPreview.value = null; page.value = 1; filter.value = ''; await router.replace({ query: { ...route.query, task: result.id } }); await refresh(); ElMessage.success('分类任务已创建') })
}
async function control(action: string) {
  if (!task.value) return
  if (action === 'cancel') { try { await ElMessageBox.confirm('停止剩余歌曲的分类，保留已有建议及已应用结果。已经写入的分类不会自动撤销；终止后不能继续此任务。', '终止分类任务', { type: 'warning', confirmButtonText: '终止任务' }) } catch { return } }
  await perform(async () => { await classification.control(task.value!.id, action); await refresh(); ElMessage.success('任务状态已更新') })
}
async function retry(item: Item) {
  if (!task.value) return
  try { await ElMessageBox.confirm('将以当前歌曲信息重新生成，仍使用本任务模型、词表和自动应用规则。已应用及人工确认分类会受保护。词表已变化时请新建任务。', '重新生成分类') } catch { return }
  await perform(async () => { await classification.retry(task.value!.id, item.id); await refresh(); ElMessage.success('已加入重新生成队列') })
}
function openReview(item: Item) { reviewing.value = item; reviewDims.value = (Object.keys(item.suggestion?.dimensions ?? {}) as Dimension[]).filter(d => item.suggestion!.dimensions[d]!.length && !item.current.dimensions[d]?.locked) }
async function applyReview() {
  if (!task.value || !reviewing.value) return
  const item = reviewing.value
  if (reviewDims.value.some(dim => item.current.dimensions[dim]?.confirmed)) { try { await ElMessageBox.confirm('所选维度包含人工确认分类，确认后将替换这些维度。锁定维度不能覆盖。', '确认修改分类', { type: 'warning' }) } catch { return } }
  await perform(async () => { await classification.apply(task.value!.id, item.id, requestId(JSON.stringify([task.value!.id, item.id, item.current.revision, reviewDims.value])), item.current.revision, reviewDims.value); reviewing.value = null; await refresh(); ElMessage.success('所选分类已确认，未选维度保留') })
}
async function saveTag() {
  if (!tagEdit.value) return
  const edit = tagEdit.value
  await perform(async () => { await classification.saveTag({ dimension: edit.dimension, name: edit.name, aliases: edit.aliases.split(/[、,\n]/).map(a => a.trim()).filter(Boolean), active: edit.active, revision: edit.revision }, edit.id); tags.value = await classification.tags(); tagEdit.value = null; ElMessage.success('词表已保存；已有任务采用原词表快照，受影响建议需新建任务') })
}
function openTag(tag?: Tag) { tagEdit.value = tag ? { ...tag, aliases: tag.aliases.join('、') } : { dimension: 'CUSTOM', name: '', aliases: '', active: true, revision: 0 } }
async function changed() { try { tags.value = await classification.tags(); await refresh() } catch (e) { notifyFailure(e) } }
watch(() => route.query.task, () => { page.value = 1; filter.value = ''; void refresh() })
onMounted(async () => { try { await Promise.all([readSettings(), classification.tags().then(v => tags.value = v)]); await refresh() } catch (e) { notifyFailure(e) } poll() })
onBeforeUnmount(() => { active = false; generation++; clearTimeout(timer) })
</script>
<template>
  <section class="classification-page management-page">
    <div class="page-heading"><div><h1>歌曲分类</h1><p class="page-description">结合已有元数据整理语种、发行年代、风格、情绪和场景，供后续手机与电视找歌使用。</p></div><ElButton @click="router.push('/library/songs')">返回歌曲管理</ElButton></div>
    <ElAlert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <div class="toolbar"><ElButton :type="tab === 'tasks' ? 'primary' : 'default'" @click="tab = 'tasks'">分类任务</ElButton><ElButton :type="tab === 'tags' ? 'primary' : 'default'" @click="tab = 'tags'">分类词表</ElButton><ElButton :aria-expanded="settingsOpen" @click="settingsOpen = !settingsOpen">{{ settingsOpen ? '收起' : '展开' }}模型设置</ElButton></div>
    <ElCard v-if="settingsOpen" shadow="never"><h2>分类模型设置</h2><p class="panel-description">使用兼容 Chat Completions 的 JSON Schema 结构化输出协议。仅发送歌曲信息与词表，不发送媒体文件、路径或凭据给模型正文。远程接口会接收歌曲信息。</p>
      <ElForm class="settings-form" @submit.prevent="saveSettings" @input="configDirty = true" @change="configDirty = true"><ElCheckbox v-model="config.enabled" :disabled="busy">启用分类模型</ElCheckbox><label>完整接口地址<ElInput v-model="config.endpoint" placeholder="https://模型服务/v1/chat/completions" aria-label="分类模型地址" maxlength="2048" :disabled="busy" /></label><label>模型名称<ElInput v-model="config.model" aria-label="分类模型名称" :disabled="busy" maxlength="200" /></label><label>密钥 {{ hasKey ? '（已保存；留空保留）' : '（本地无鉴权服务可留空）' }}<ElInput v-model="config.apiKey" type="password" autocomplete="new-password" aria-label="分类模型密钥" :disabled="busy" /></label><ElCheckbox v-model="config.clearKey" :disabled="busy">清除已保存密钥</ElCheckbox><div class="toolbar"><label>超时（秒）<ElInputNumber v-model="config.timeoutSeconds" :min="5" :max="180" :disabled="busy" /></label><label>请求间隔（秒）<ElInputNumber v-model="config.intervalSeconds" :min="2" :max="300" :disabled="busy" /></label></div><p class="panel-description">串行请求；HTTP 429 至少冷却 60 秒。保存会暂停运行任务，任务保留原配置快照。更换地址需重填或清除密钥。</p><div><ElButton type="primary" native-type="submit" :loading="busy">保存设置</ElButton><ElButton :disabled="busy || !settingsLoaded || configDirty || !config.enabled" @click="testConnection">测试已保存配置</ElButton></div></ElForm>
    </ElCard>
    <template v-if="tab === 'tasks'">
      <ElCard shadow="never"><h2>新建分类任务</h2><div class="toolbar"><ElCheckbox v-model="all" :disabled="busy">全部歌曲（最多 5000 首）</ElCheckbox><span>{{ all ? '将处理全部歌曲' : `歌曲管理已选 ${selectedIds.length} 首` }}</span><ElButton v-if="!all && !selectedIds.length" @click="router.push('/library/songs')">前往选择歌曲</ElButton></div><div class="toolbar"><strong>分类维度</strong><ElCheckbox v-for="dim in aiDimensions" :key="dim" :model-value="dimensions.includes(dim)" @change="v => toggleList(dimensions, dim, !!v)" :disabled="busy">{{ dimensionNames[dim] }}</ElCheckbox></div><div class="toolbar"><ElCheckbox v-model="auto" :disabled="busy">自动应用所选维度的 AI 推断</ElCheckbox><ElCheckbox v-for="dim in dimensions" v-show="auto" :key="dim" :model-value="automatic.includes(dim)" @change="v => toggleList(automatic, dim, !!v)" :disabled="busy">{{ dimensionNames[dim] }}</ElCheckbox></div><p class="panel-description">自动应用默认关闭。允许推断自动发布并不保证分类正确；人工确认和锁定维度受保护。未知保留为空；新标签只生成建议。发行年代不代表首次发行年代。</p><ElButton type="primary" :disabled="busy || !settingsLoaded || configDirty || !config.enabled || !dimensions.length || (!all && !selectedIds.length) || (auto && !automatic.filter(d => dimensions.includes(d)).length)" @click="preview">预览输入并启动</ElButton><span v-if="!config.enabled || configDirty" class="panel-description"> 请先保存并启用模型配置。</span></ElCard>
      <ElCard shadow="never"><div class="card-heading"><h2>分类任务记录</h2><ElButton :loading="loading" @click="refresh">刷新</ElButton></div><div class="task-history"><ElButton v-for="t in tasks" :key="t.id" :type="task?.id === t.id ? 'primary' : 'default'" @click="router.replace({ query: { ...route.query, task: t.id } })">{{ new Date(t.createdAt).toLocaleString() }} · {{ statusNames[t.status] }} · {{ t.total }} 首</ElButton><p v-if="!tasks.length">尚未创建分类任务。</p></div><ElButton :disabled="taskPage === 0 || loading" @click="taskPage--; refresh()">上一页记录</ElButton><ElButton :disabled="tasks.length < 20 || loading" @click="taskPage++; refresh()">下一页记录</ElButton></ElCard>
      <ElCard v-if="task" shadow="never"><div class="card-heading"><div><h2>{{ statusNames[task.status] }}</h2><p class="panel-description">模型：{{ task.model }} · 最近读取：{{ loadedAt }} · 自动应用：{{ dimensionLabels(task.autoDimensions) || '关闭' }}</p></div><div class="toolbar"><ElButton v-if="task.status === 'RUNNING'" :disabled="busy" @click="control('pause')">暂停</ElButton><ElButton v-if="task.status === 'PAUSED'" :disabled="busy || !config.enabled" @click="control('resume')">继续</ElButton><ElButton v-if="['RUNNING','PAUSED'].includes(task.status)" :disabled="busy" type="danger" plain @click="control('cancel')">终止</ElButton><ElButton :loading="loading" @click="refresh">刷新进度</ElButton></div></div><ElProgress :percentage="progress" /><p>已完成处理 {{ task.completed }} / {{ task.total }} 首</p><div class="stats"><ElButton v-for="(count, state) in task.counts" :key="state" text @click="filter = state; page = 1; refresh()">{{ statusNames[state] }} {{ count }}</ElButton></div><p class="panel-description">各状态互斥；待审核已经完成生成，不等于写入成功。部分维度自动应用后仍有建议时计入待审核，实际结果见审核详情与历史。终止项计入处理结束。</p>
        <div class="toolbar"><label>明细状态 <select v-model="filter" @change="page = 1; refresh()"><option value="">全部状态</option><option v-for="state in Object.keys(task.counts)" :key="state" :value="state">{{ statusNames[state] }}</option></select></label></div>
        <ElTable :data="task.items" row-key="id" empty-text="该条件下没有任务歌曲"><ElTableColumn label="歌曲" min-width="180"><template #default="{ row }"><strong>{{ row.input.title || '未识别歌名' }}</strong><p>{{ row.input.artists.join('、') || '未识别歌手' }}</p><small>{{ row.input.album || '专辑未知' }}</small></template></ElTableColumn><ElTableColumn label="分类建议 / 当前结果" min-width="290"><template #default="{ row }"><p v-for="dim in task.dimensions" :key="dim"><strong>{{ dimensionNames[dim] }}：</strong>{{ names(row.suggestion?.dimensions[dim]) }}<small v-if="row.current.dimensions[dim]"> · 当前 {{ names(row.current.dimensions[dim].tagIds) }}（{{ originNames[row.current.dimensions[dim].origin] }}{{ row.current.dimensions[dim].locked ? ' · 锁定' : '' }}）</small></p><p v-if="row.suggestion?.newTagSuggestions.length" class="warning">新标签建议（未发布）：{{ row.suggestion.newTagSuggestions.join('、') }}</p></template></ElTableColumn><ElTableColumn label="状态" min-width="180"><template #default="{ row }"><ElTag :type="row.status === 'FAILED' ? 'danger' : row.status === 'APPLIED' ? 'success' : row.status === 'REVIEW' ? 'warning' : 'info'">{{ statusNames[row.status] }}</ElTag><p v-if="row.error" class="warning">{{ row.error }}</p></template></ElTableColumn><ElTableColumn label="操作" min-width="160"><template #default="{ row }"><ElButton v-if="row.status === 'REVIEW'" link type="primary" :disabled="busy" @click="openReview(row as Item)">审核建议</ElButton><ElButton v-if="['FAILED','REVIEW','UNCHANGED'].includes(row.status) && task.status !== 'CANCELLED'" link :disabled="busy || !config.enabled" @click="retry(row as Item)">{{ row.status === 'FAILED' ? '重试' : '重新生成' }}</ElButton><ElButton link :disabled="busy || row.status === 'PROCESSING'" @click="editing = [row.songId]">人工整理 / 历史</ElButton></template></ElTableColumn></ElTable><ElPagination :current-page="page" :total="task.totalElements" :page-size="20" layout="total, prev, pager, next" @current-change="p => { page = p; refresh() }" />
      </ElCard>
    </template>
    <ElCard v-else shadow="never"><div class="card-heading"><h2>分类词表</h2><ElButton type="primary" @click="openTag()">新增标签</ElButton></div><div class="toolbar"><ElInput v-model="tagSearch" placeholder="搜索标签或别名" aria-label="搜索分类标签" /><select v-model="tagDimension" aria-label="分类维度筛选"><option value="">全部维度</option><option v-for="(name, dim) in dimensionNames" :key="dim" :value="dim">{{ name }}</option></select></div><p class="panel-description">稳定维度供各端复用。停用标签退出正式筛选，但保留历史与已存关联；人工确认不会被 AI 自动覆盖。</p><ElTable :data="visibleTags" row-key="id"><ElTableColumn label="维度" width="110"><template #default="{ row }">{{ dimensionNames[row.dimension as Dimension] }}</template></ElTableColumn><ElTableColumn prop="name" label="标签" min-width="130" /><ElTableColumn label="别名" min-width="180"><template #default="{ row }">{{ row.aliases.join('、') || '—' }}</template></ElTableColumn><ElTableColumn label="状态" width="90"><template #default="{ row }">{{ row.active ? '启用' : '停用' }}</template></ElTableColumn><ElTableColumn label="歌曲数" width="100"><template #default="{ row }"><ElButton link type="primary" :disabled="!row.active" @click="router.push({ path: '/library/songs', query: { tagIds: row.id } })">{{ row.count }}</ElButton></template></ElTableColumn><ElTableColumn label="操作" width="90"><template #default="{ row }"><ElButton link type="primary" @click="openTag(row as Tag)">编辑</ElButton></template></ElTableColumn></ElTable></ElCard>
    <ElDialog :model-value="!!pendingPreview" title="确认分类输入" width="min(780px, calc(100vw - 24px))" :close-on-click-modal="false" :show-close="!busy" @close="pendingPreview = null; pendingStart = null"><template v-if="pendingPreview"><p>共 {{ pendingPreview.total }} 首，以下预览前 {{ pendingPreview.items.length }} 首。模型：{{ pendingPreview.model.model }}</p><ElAlert title="将发送这些歌曲信息及词表到已配置模型服务。不会发送媒体、路径或完整曲库。AI 推断可能不准确。" type="warning" :closable="false" /><p>自动应用维度：{{ dimensionLabels(pendingStart?.autoDimensions ?? []) || '关闭，全部待人工确认' }}</p><ElTable :data="pendingPreview.items" max-height="340"><ElTableColumn prop="title" label="歌名" /><ElTableColumn label="歌手"><template #default="{ row }">{{ row.artists.join('、') }}</template></ElTableColumn><ElTableColumn prop="album" label="专辑" /><ElTableColumn prop="releaseDate" label="发行日期" /><ElTableColumn prop="language" label="已有语种" /><ElTableColumn prop="version" label="文件名版本" /><ElTableColumn label="质量标签"><template #default="{ row }">{{ row.qualityTags.join('、') }}</template></ElTableColumn></ElTable></template><template #footer><ElButton :disabled="busy" @click="pendingPreview = null; pendingStart = null">取消</ElButton><ElButton type="primary" :loading="busy" @click="start">确认启动</ElButton></template></ElDialog>
    <ElDialog :model-value="!!reviewing" title="审核分类建议" width="min(840px, calc(100vw - 24px))" :show-close="!busy" :close-on-click-modal="false" @close="reviewing = null"><template v-if="reviewing"><h3>{{ reviewing.input.title }} · {{ reviewing.input.artists.join('、') }}</h3><p class="panel-description">勾选维度会替换该维度分类并标为人工确认。未勾选及空建议保留现状；已锁定不可应用。</p><div v-for="dim in task?.dimensions" :key="dim" class="review-row"><ElCheckbox :model-value="reviewDims.includes(dim)" @change="v => toggleList(reviewDims, dim, !!v)" :disabled="busy || !reviewing.suggestion?.dimensions[dim]?.length || reviewing.current.dimensions[dim]?.locked">{{ dimensionNames[dim] }}</ElCheckbox><div><p>当前：{{ names(reviewing.current.dimensions[dim]?.tagIds) }} {{ reviewing.current.dimensions[dim]?.locked ? '（已锁定）' : '' }}</p><p>建议：{{ names(reviewing.suggestion?.dimensions[dim]) }}</p><small>{{ reviewing.suggestion?.reasons[dim] }}</small></div></div><ElAlert v-if="error" :title="error" type="error" :closable="false" /></template><template #footer><ElButton :disabled="busy" @click="reviewing = null">关闭</ElButton><ElButton type="primary" :disabled="!reviewDims.length" :loading="busy" @click="applyReview">确认所选维度</ElButton></template></ElDialog>
    <ElDialog :model-value="!!tagEdit" title="维护分类标签" width="min(520px, calc(100vw - 24px))" :show-close="!busy" @close="tagEdit = null"><ElForm v-if="tagEdit" class="settings-form" @submit.prevent="saveTag"><label>维度<select v-model="tagEdit.dimension" :disabled="!!tagEdit.id || busy"><option v-for="(name, dim) in dimensionNames" :key="dim" :value="dim">{{ name }}</option></select></label><label>标签名称<ElInput v-model="tagEdit.name" maxlength="80" :disabled="busy" /></label><label>别名（顿号分隔）<ElInput v-model="tagEdit.aliases" :disabled="busy" /></label><ElCheckbox v-model="tagEdit.active" :disabled="busy">启用</ElCheckbox><ElAlert v-if="error" :title="error" type="error" :closable="false" /><ElButton type="primary" native-type="submit" :loading="busy">保存标签</ElButton></ElForm></ElDialog>
    <ClassificationEditor v-if="editing.length" :song-ids="editing" @close="editing = []" @changed="changed" />
  </section>
</template>
<style scoped>
.classification-page { display: grid; gap: 16px; min-width: 0; }.toolbar,.card-heading,.task-history,.stats { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; }.toolbar { margin: 12px 0; }.toolbar .el-input { max-width: 320px; }.card-heading { justify-content: space-between; margin-bottom: 12px; }.task-history { margin-bottom: 12px; }.task-history .el-button { margin: 0; }.settings-form { display: grid; gap: 12px; max-width: 760px; margin-top: 14px; }.settings-form label { display: grid; gap: 6px; }.review-row { display: flex; gap: 20px; padding: 12px 0; border-bottom: 1px solid var(--el-border-color-light); }.review-row > div { min-width: 0; overflow-wrap: anywhere; }.classification-page p { line-height: 1.65; }.classification-page :deep(.el-table p) { font-size: 12px; margin-top: 3px; }.classification-page small { color: var(--el-text-color-secondary); }.warning { color: var(--el-color-warning-dark-2); font-size: 12px; overflow-wrap: anywhere; }.classification-page :deep(.el-pagination) { margin-top: 14px; flex-wrap: wrap; }.classification-page .el-button + .el-button { margin-left: 0; }
@media(max-width: 650px) { .review-row { flex-direction: column; gap: 0; }.toolbar label { max-width: 100%; }.page-heading { align-items: flex-start; } }
</style>
